921	        if (self.pure && ctx.annotations()) || ctx.manual_pure_functions(&self.callee) {
922	            return self.arguments.iter().any(|e| e.may_have_side_effects(ctx));
923	        }
924	
925	        if let Expression::Identifier(ident) = &self.callee
926	            && ctx.is_global_reference(ident)
927	        {
928	            let name = ident.name.as_str();
929	            if name == "String" {
930	                if self.arguments.iter().any(|e| e.may_have_side_effects(ctx)) {
931	                    return true;
932	                }
933	                // String(value) calls ToPrimitive on object-like/unknown values.
934	                return self.arguments.first().is_some_and(|arg| {
935	                    arg.as_expression()
936	                        .is_none_or(|expr| expr.to_primitive(ctx).is_string().is_none())
937	                });
938	            }
939	            if name == "Number" {
940	                if self.arguments.iter().any(|e| e.may_have_side_effects(ctx)) {
941	                    return true;
942	                }
943	                // Number(value) throws on Symbol and can execute user code during ToPrimitive.
944	                return self.arguments.first().is_some_and(|arg| {
945	                    arg.as_expression()
946	                        .is_none_or(|expr| expr.to_primitive(ctx).is_symbol() != Some(false))
947	                });
948	            }
949	            if name == "BigInt" {
950	                if self.arguments.iter().any(|e| e.may_have_side_effects(ctx)) {
951	                    return true;
952	                }
953	                // BigInt(value) throws for missing/invalid values and can execute user code during ToPrimitive.
954	                let Some(expr) = self.arguments.first().and_then(Argument::as_expression) else {
955	                    return true;
956	                };
957	                if matches!(
958	                    expr.to_primitive(ctx),
959	                    ToPrimitiveResult::Undetermined
960	                        | ToPrimitiveResult::Undefined
961	                        | ToPrimitiveResult::Null
962	                        | ToPrimitiveResult::Symbol
963	                ) {
964	                    return true;
965	                }
966	                return expr.to_big_int(ctx).is_none();
967	            }
