///
/// These never invoke user-defined coercion/iteration code, so `new X(anything)` is pure as long
/// as evaluating the argument itself is pure. This includes:
/// - `Object`: wraps the value (or creates a plain object) without coercing it.
/// - `Boolean`: performs `ToBoolean`, which never runs user code.
/// - `Error` family: stores the argument as-is.
/// - `ArrayBuffer`: reads the byte length via `ToIndex`, handled by the argument's own side effects.
#[rustfmt::skip]
fn is_pure_constructor(name: &str) -> bool {
    matches!(name, "ArrayBuffer"
            | "Boolean" | "Error" | "EvalError" | "RangeError" | "ReferenceError"
            | "SyntaxError" | "TypeError" | "URIError" | "Object")
}

